import{_ as e,o as r,c as t,a2 as s}from"./chunks/framework.DuPBmefI.js";const h=JSON.parse('{"title":"喇沙书院 · 2020-21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-797ec2e8","school_zh":"喇沙书院","school_en":"—","grade":"s1","year":"2020-21","year_label":"2020-21年度","type":"interview","title":"喇沙书院 · 2020-21年度 · 中一 · 面试","anonymous":true,"source_ids":["C1821-LSC-2021-FIRST","C1821-LSC-2021-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-797ec2e8/s1/2020-21-interview.md","filePath":"reports/school-797ec2e8/s1/2020-21-interview.md"}'),n={name:"reports/school-797ec2e8/s1/2020-21-interview.md"};function a(p,o,c,l,g,i){return r(),t("div",null,[...o[0]||(o[0]=[s('<h1 id="喇沙书院-·-2020-21年度-·-中一-·-面试" tabindex="-1">喇沙书院 · 2020-21年度 · 中一 · 面试 <a class="header-anchor" href="#喇沙书院-·-2020-21年度-·-中一-·-面试" aria-label="Permalink to &quot;喇沙书院 · 2020-21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-797ec2e8">← 返回喇沙书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-lsc-2021-first" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-lsc-2021-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-lsc-2021-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>双语阅读与表达</strong></p><p>一组约10分钟，先英文再中文，包含朗读、图片及短讲；短讲准备约1至2分钟、讲2分钟。不同文章未必都设追问。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>文章、诗歌与图片</strong></p><p>朗读诗歌或短文，主题有老鼠商议为猫挂铃、糟糕旅行。图片题包括男子打鼾、同床女士用枕头盖耳，问她为何生气；另有众人看手机、孩子拿篮球却无人理会的三图，要求说明要传达什么。</p><p><strong>个人与校园议题</strong></p><p>希望去哪旅行及原因、最深刻的事；学校增设哪种课外活动，是否参加体育活动，现代青少年面对什么问题。</p></blockquote><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>诗文理解</strong></p><p>阅读因故乡战乱不能回乡的故事，用一词或一句形容笔者故乡；另有战国勇士保卫家园的文章，问后人为何难忘古人。</p><p><strong>设计、自喻与疫情短讲</strong></p><p>为老人院或长者生活设计机器人；用文具形容自己；若回到过去最想与哪位历史人物交谈。另问报读原因、成绩情况，或就疫情对自己的影响、体会和收获讲2分钟。</p></blockquote><h2 id="record-c1821-lsc-2021-second" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-lsc-2021-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-lsc-2021-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>先学生、后家长</strong></p><p>学生先见校长及两位外籍修士，携带成绩表和证书正本供三人传阅；主要由一位修士发问，校长最后用普通话补问。之后学生离开，家长进入。</p></blockquote><blockquote><p><strong>学生面谈：</strong> 英语</p><p><strong>家庭、志向与个人资料</strong></p><p>介绍家庭、下次想去哪里旅行、是否有其他中学录取、自己的短处、课外活动、理想及最喜欢的科目。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>中文弱项与写作构思</strong></p><p>中文哪方面最弱、为什么；若把本次面试经历写成作文，会怎样写。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 英语</p><p><strong>核对孩子的回答</strong></p><p>由修士用英语提问，主要重问或延伸孩子刚才的回答，请家长进一步解释。家长觉得交流友善，没有遇到刁钻问题。</p></blockquote>',20)])])}const u=e(n,[["render",a]]);export{h as __pageData,u as default};
